<div class="container py-5"><h1>إتمام الطلب</h1><div class="row g-4"><div class="col-lg-7"><form method="post" class="card card-body"><?= csrf_field() ?><label class="form-label">الاسم بالكامل</label><input required name="customer_name" class="form-control" value="<?= e(current_user()['full_name']??'') ?>"><label class="form-label mt-3">رقم الهاتف</label><input required name="customer_phone" class="form-control" dir="ltr" value="<?= e(current_user()['phone']??'') ?>"><label class="form-label mt-3">العنوان بالتفصيل</label><textarea required name="customer_address" class="form-control" rows="3"><?= e(current_user()['default_address']??'') ?></textarea><label class="form-label mt-3">المدينة</label><input required name="customer_city" class="form-control" value="<?= e(current_user()['city']??setting('store_city_ar','الفيوم')) ?>"><label class="form-label mt-3">ملاحظات</label><textarea name="notes" class="form-control" rows="2"></textarea><button class="btn btn-success btn-lg mt-3" <?= !$items?'disabled':'' ?>>تأكيد الطلب — <?= money($totals['total']) ?></button></form></div><div class="col-lg-5"><div class="card card-body"><h5>ملخص الطلب</h5><?php foreach($items as $i): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($i['product_name']) ?> × <?= $i['quantity'] ?></span><b><?= money($i['unit_price']*$i['quantity']) ?></b></div><?php endforeach; ?><div class="mt-3">الإجمالي: <b><?= money($totals['total']) ?></b></div></div></div></div></div>
